// Reads beneath its granted directory, runs its granted program, dials its
// granted host: each literal is one its grant covers.
import { netAddress, tcpConnect } from "nish:net";

const dial = (): boolean => {
  const addr: u8[] = [];
  return netAddress(addr, "127.0.0.1", 9) >= 0 && tcpConnect(addr) >= 0;
};

const load = (): i32 => readFileSync("data/settings.conf").length;

const run = (): i32 => spawnSync(["true"]);

export const work = (): i32 => (dial() ? load() + run() : 2);
